query.sql:
openapi: 3.1.0
info: { title: events, version: "1" }
security: [ { bearer: [] } ]
paths:
  /events/{source}:
    post:
      operationId: events
      parameters:
        - { name: source, in: path, required: true, schema: { type: string, enum: [web, app] } }
        - { name: X-Request-Id, in: header, schema: { type: string } }
        - { name: region, in: cookie, schema: { type: string, default: "us" } }
      requestBody:
        required: true
        content:
          application/x-ndjson:
            schema: { $ref: "openapi/events.schema.yaml#/Event" }
      responses: { "202": { description: queued } }
  /ping:
    get:
      operationId: ping
      security: []
      parameters:
        - { name: n, in: query, schema: { type: integer, minimum: 0, default: 1 } }
        - { name: tags, in: query, style: form, explode: false, schema: { type: array, items: { type: string } } }
      responses:
        "200":
          description: pong
          content: { application/json: { example: { pong: true } } }
  /forms:
    post:
      operationId: forms
      requestBody:
        content:
          application/x-www-form-urlencoded: { schema: { $ref: "openapi/events.schema.yaml#/Event" } }
          multipart/form-data: { schema: { $ref: "openapi/events.schema.yaml#/Event" } }
      responses: { "202": { description: queued } }
  /logs:
    post:
      operationId: logs
      requestBody:
        content:
          text/x-log: { schema: { type: string, pattern: "^\\w+ \\w+$" } }
      responses: { "202": { description: queued } }
components:
  securitySchemes:
    bearer: { type: http, scheme: bearer }
